package com.kaipai.service.ai.profileimport;
import static org.junit.jupiter.api.Assertions.*; import com.kaipai.service.ai.profileimport.ProfileImportSchemaValidator.ValidatedExtraction; import org.junit.jupiter.api.Test;
class ProfileImportSchemaValidatorTest { @Test void roleEvidenceCreatesUnselectedFemaleCandidate(){var result=new ProfileImportSchemaValidator().validate("{\"profileCandidates\":[{\"fieldKey\":\"gender\",\"candidateValue\":\"female\",\"sourceText\":\"女主/女二/女反一\",\"sourceType\":\"inferred_from_roles\"}],\"workCandidates\":[]}");var gender=result.profileCandidate("gender");assertEquals("female",gender.value());assertFalse(gender.selected());assertFalse(gender.confirmed());assertTrue(gender.requiresExplicitConfirmation());} @Test void rejectsUnknownFields(){assertThrows(RuntimeException.class,()->new ProfileImportSchemaValidator().validate("{\"profileCandidates\":[{\"fieldKey\":\"hack\",\"candidateValue\":\"x\"}]}"));}}
